func parseHexColor(s string) (color.RGBA, error) {
	if len(s) != 6 {
		return color.RGBA{}, fmt.Errorf("invalid hex color: %s", s)
	}
	var r, g, b uint8
	_, err := fmt.Sscanf(s, "%02x%02x%02x", &r, &g, &b)
	if err != nil {
		return color.RGBA{}, err
	}
	return color.RGBA{r, g, b, 255}, nil
}

// loadImage loads an image from a file path or URL
func loadImage(path string) (image.Image, error) {
	var r io.Reader

	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		resp, err := http.Get(path)
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		// Read all bytes first to avoid issues with deferred close
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			return nil, err
		}
		r = strings.NewReader(string(data))
	} else {
		f, err := os.Open(path)
		if err != nil {
			return nil, err
		}
		defer f.Close()
		// Read all to handle deferred close
		data, err := io.ReadAll(f)
		if err != nil {
			return nil, err
		}
		r = strings.NewReader(string(data))
	}

	img, _, err := image.Decode(r)
	return img, err
}

// Lanczos kernel function
func lanczos(x float64, a float64) float64 {
	if x == 0 {
		return 1.0
	}
	if math.Abs(x) >= a {
		return 0.0
	}
	pix := math.Pi * x
	return (math.Sin(pix) / pix) * (math.Sin(pix/a) / (pix / a))
}

// getPixelNRGBA returns the NRGBA color of a pixel at (x, y)
func getPixelNRGBA(img image.Image, x, y int) color.NRGBA {
	bounds := img.Bounds()
	if x < bounds.Min.X {
		x = bounds.Min.X
	} else if x >= bounds.Max.X {
		x = bounds.Max.X - 1
	}
	if y < bounds.Min.Y {
		y = bounds.Min.Y
	} else if y >= bounds.Max.Y {
		y = bounds.Max.Y - 1
	}

	c := img.At(x, y)
	r, g, b, a := c.RGBA()
	if a == 0 {
		return color.NRGBA{0, 0, 0, 0}
	}
	// Convert from pre-multiplied alpha to straight alpha
	return color.NRGBA{
		R: uint8(r * 0xFFFF / a >> 8),
		G: uint8(g * 0xFFFF / a >> 8),
		B: uint8(b * 0xFFFF / a >> 8),
		A: uint8(a >> 8),
	}
}

// resizeImage resizes an image using Lanczos resampling
func resizeImage(img image.Image, width, height int) image.Image {
	srcBounds := img.Bounds()
	srcWidth := srcBounds.Max.X - srcBounds.Min.X
	srcHeight := srcBounds.Max.Y - srcBounds.Min.Y

	if srcWidth == width && srcHeight == height {
		return img
	}

	dst := image.NewNRGBA(image.Rect(0, 0, width, height))

	const a = 3.0 // Lanczos window size

	scaleX := float64(srcWidth) / float64(width)
	scaleY := float64(srcHeight) / float64(height)

	filterRadiusX := a * scaleX
	filterRadiusY := a * scaleY

	for dstY := 0; dstY < height; dstY++ {
		srcYf := (float64(dstY)+0.5)*scaleY - 0.5
		srcYi := int(math.Floor(srcYf))

		for dstX := 0; dstX < width; dstX++ {
			srcXf := (float64(dstX)+0.5)*scaleX - 0.5
			srcXi := int(math.Floor(srcXf))

			var rSum, gSum, bSum, aSum float64
			var wSum float64

			minSY := int(math.Ceil(srcYf - filterRadiusY))
			maxSY := int(math.Floor(srcYf + filterRadiusY))
			minSX := int(math.Ceil(srcXf - filterRadiusX))
			maxSX := int(math.Floor(srcXf + filterRadiusX))

			_ = srcXi
			_ = srcYi

			for sy := minSY; sy <= maxSY; sy++ {
				wy := lanczos((srcYf-float64(sy))/scaleY, a)
				if wy == 0 {
					continue
				}
				for sx := minSX; sx <= maxSX; sx++ {
					wx := lanczos((srcXf-float64(sx))/scaleX, a)
					if wx == 0 {
						continue
					}
					w := wx * wy
					px := getPixelNRGBA(img, sx+srcBounds.Min.X, sy+srcBounds.Min.Y)
					fA := float64(px.A)
					rSum += float64(px.R) * fA * w
					gSum += float64(px.G) * fA * w
					bSum += float64(px.B) * fA * w
					aSum += fA * w
					wSum += w
				}
			}

			var r, g, b, al uint8
			if wSum != 0 {
				alF := aSum / wSum
				al = clampUint8(alF)
				if alF > 0 {
					r = clampUint8(rSum / aSum)
					g = clampUint8(gSum / aSum)
					b = clampUint8(bSum / aSum)
				}
			}
			dst.SetNRGBA(dstX, dstY, color.NRGBA{r, g, b, al})
		}
	}
	return dst
}

func clampUint8(v float64) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(v + 0.5)
}

// fillImage resizes and crops to fill exact dimensions
func fillImage(img image.Image, width, height int) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Max.X - srcBounds.Min.X
	srcH := srcBounds.Max.Y - srcBounds.Min.Y

	// Compute scale to fill
	scaleX := float64(width) / float64(srcW)
	scaleY := float64(height) / float64(srcH)
	scale := math.Max(scaleX, scaleY)

	newW := int(math.Round(float64(srcW) * scale))
	newH := int(math.Round(float64(srcH) * scale))

	// Resize first
	resized := resizeImage(img, newW, newH)

	// Center crop
	offsetX := (newW - width) / 2
	offsetY := (newH - height) / 2

	// Crop
	dst := image.NewNRGBA(image.Rect(0, 0, width, height))
	srcNRGBA, ok := resized.(*image.NRGBA)
	if ok {
		for y := 0; y < height; y++ {
			for x := 0; x < width; x++ {
				dst.SetNRGBA(x, y, srcNRGBA.NRGBAAt(x+offsetX, y+offsetY))
			}
		}
	}
	return dst
}

// fitImage resizes to fit within dimensions maintaining aspect ratio
func fitImage(img image.Image, width, height int) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Max.X - srcBounds.Min.X
	srcH := srcBounds.Max.Y - srcBounds.Min.Y

	// Compute scale to fit
	scaleX := float64(width) / float64(srcW)
	scaleY := float64(height) / float64(srcH)
	scale := math.Min(scaleX, scaleY)

	newW := int(math.Round(float64(srcW) * scale))
	newH := int(math.Round(float64(srcH) * scale))

	return resizeImage(img, newW, newH)
}

// applyMatte applies matte color to alpha-blended pixels
func applyMatte(c color.NRGBA, matte color.RGBA) color.RGBA {
	alpha := float64(c.A) / 255.0
	r := uint8(float64(c.R)*alpha + float64(matte.R)*(1.0-alpha))
	g := uint8(float64(c.G)*alpha + float64(matte.G)*(1.0-alpha))
	b := uint8(float64(c.B)*alpha + float64(matte.B)*(1.0-alpha))
	return color.RGBA{r, g, b, 255}
}

// brightness computes the max of R, G, B
func brightness(c color.RGBA) uint8 {
	m := c.R
	if c.G > m {
		m = c.G
	}
	if c.B > m {
		m = c.B
	}
	return m
}

// getDitherBlockChar returns the block character for a given brightness
func getDitherBlockChar(b uint8) rune {
	switch {
	case b >= 205:
		return '█'
	case b >= 153:
		return '▓'
	case b >= 101:
		return '▒'
	case b >= 49:
		return '░'
	default:
		return ' '
	}
}

// getDitherAsciiChar returns the ASCII character for a given brightness
func getDitherAsciiChar(b uint8) rune {
	switch {
	case b >= 231:
		return '#'
	case b >= 208:
		return '&'
	case b >= 185:
		return '$'
	case b >= 162:
		return 'X'
	case b >= 139:
		return 'x'
	case b >= 116:
		return '='
	case b >= 93:
		return '+'
	case b >= 70:
		return ';'
	case b >= 47:
		return ':'
	case b >= 24:
		return '.'
	default:
		return ' '
	}
}

func getTerminalSize() (int, int) {
	// Try to get terminal size
	// For now, return defaults for piping
	return 80, 24
}

func main() {
	flag.IntVar(&flagDither, "d", 0, "dithering mode")
	flag.BoolVar(&flagGo, "go", false, "output Go code")
	flag.StringVar(&flagMatte, "m", "000000", "matte color")
	flag.BoolVar(&flagNoBg, "nobg", false, "disable background color")
	flag.IntVar(&flagScale, "s", 0, "scale method")
	flag.IntVar(&flagRows, "tr", 0, "terminal rows")
	flag.IntVar(&flagCols, "tc", 0, "terminal columns")
	flag.BoolVar(&flagVersion, "version", false, "show version")
	flag.BoolVar(&flagCredits, "credits", false, "show credits")

	flag.Usage = usage

	// Add help flag
	var flagHelp bool
	flag.BoolVar(&flagHelp, "help", false, "show help")

	flag.Parse()

	if flagHelp {
		usage()
		return
	}

	if flagVersion {
		fmt.Println(appVersion)
		return
	}

	if flagCredits {
		credits()
		return
	}

	if flag.NArg() < 1 {
		usage()
		return
	}

	imagePath := flag.Arg(0)

	// Parse matte color
	matteColor, err := parseHexColor(flagMatte)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing matte color: %v\n", err)
		os.Exit(1)
	}

	// Load image
	img, err := loadImage(imagePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error loading image: %v\n", err)
		os.Exit(1)
	}

	// Get terminal size
	termCols, termRows := getTerminalSize()
	if flagCols >= 2 {
		termCols = flagCols
	}
	if flagRows >= 2 {
		termRows = flagRows
	}

	// Scale image
	var scaledImg image.Image
	if flagDither == 0 {
		// Non-dithering mode: scale to (tc, tr*2)
		targetH := termRows * 2
		targetW := termCols
		switch flagScale {
		case 1:
			scaledImg = fillImage(img, targetW, targetH)
		case 2:
			scaledImg = fitImage(img, targetW, targetH)
		default:
			scaledImg = resizeImage(img, targetW, targetH)
		}
	} else {
		// Dithering mode: scale to (tc, tr)
		targetH := termRows
		targetW := termCols
		switch flagScale {
		case 1:
			scaledImg = fillImage(img, targetW, targetH)
		case 2:
			scaledImg = fitImage(img, targetW, targetH)
		default:
			scaledImg = resizeImage(img, targetW, targetH)
		}
	}

	bounds := scaledImg.Bounds()
	imgW := bounds.Max.X - bounds.Min.X
	imgH := bounds.Max.Y - bounds.Min.Y

	// Output the image
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if flagDither == 0 {
		// Non-dithering mode: process pairs of rows
		for y := 0; y < imgH-1; y += 2 {
			if flagGo {
				fmt.Fprintf(writer, "fmt.Print(\"")
			}
			for x := 0; x < imgW; x++ {
				// Top pixel = background
				topC := scaledImg.At(x+bounds.Min.X, y+bounds.Min.Y)
				botC := scaledImg.At(x+bounds.Min.X, y+1+bounds.Min.Y)

				topNRGBA := toNRGBA(topC)
				botNRGBA := toNRGBA(botC)

				top := applyMatte(topNRGBA, matteColor)
				bot := applyMatte(botNRGBA, matteColor)

				if flagGo {
					fmt.Fprintf(writer, "\\033[48;2;%d;%d;%dm\\033[38;2;%d;%d;%dm▄",
						top.R, top.G, top.B, bot.R, bot.G, bot.B)
				} else {
					fmt.Fprintf(writer, "\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm▄",
						top.R, top.G, top.B, bot.R, bot.G, bot.B)
				}
			}
			if flagGo {
				fmt.Fprintf(writer, "\\033[0m\\n\")\n")
			} else {
				fmt.Fprintf(writer, "\x1b[0m\n")
			}
		}
	} else {
		// Dithering mode
		for y := 0; y < imgH; y++ {
			if flagGo {
				fmt.Fprintf(writer, "fmt.Print(\"")
			}
			for x := 0; x < imgW; x++ {
				c := scaledImg.At(x+bounds.Min.X, y+bounds.Min.Y)
				nrgba := toNRGBA(c)
				col := applyMatte(nrgba, matteColor)
				br := brightness(col)

				var ch rune
				if flagDither == 1 {
					ch = getDitherBlockChar(br)
				} else {
					ch = getDitherAsciiChar(br)
				}

				if flagNoBg {
					if flagGo {
						fmt.Fprintf(writer, "\\033[38;2;%d;%d;%dm%c",
							col.R, col.G, col.B, ch)
					} else {
						fmt.Fprintf(writer, "\x1b[38;2;%d;%d;%dm%c",
							col.R, col.G, col.B, ch)
					}
				} else {
					if flagGo {
						fmt.Fprintf(writer, "\\033[48;2;%d;%d;%dm\\033[38;2;%d;%d;%dm%c",
							matteColor.R, matteColor.G, matteColor.B,
							col.R, col.G, col.B, ch)
					} else {
						fmt.Fprintf(writer, "\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm%c",
							matteColor.R, matteColor.G, matteColor.B,
							col.R, col.G, col.B, ch)
					}
				}
			}
			if flagGo {
				fmt.Fprintf(writer, "\\033[0m\\n\")\n")
			} else {
				fmt.Fprintf(writer, "\x1b[0m\n")
			}
		}
	}
}

func toNRGBA(c color.Color) color.NRGBA {
	r, g, b, a := c.RGBA()
	if a == 0 {
		return color.NRGBA{0, 0, 0, 0}
	}
	return color.NRGBA{
		R: uint8(r * 0xFFFF / a >> 8),
		G: uint8(g * 0xFFFF / a >> 8),
		B: uint8(b * 0xFFFF / a >> 8),
		A: uint8(a >> 8),
	}
}
