func parseHexColor(s string) (color.RGBA, error) {
	if len(s) != 6 {
		return color.RGBA{}, fmt.Errorf("invalid hex color: %s", s)
	}
	var r, g, b uint8
	_, err := fmt.Sscanf(s, "%02x%02x%02x", &r, &g, &b)
	if err != nil {
		return color.RGBA{}, err
	}
	return color.RGBA{r, g, b, 255}, nil
}

// loadImage loads an image from a file path or URL
func loadImage(path string) (image.Image, error) {
	var reader io.Reader

	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		resp, err := http.Get(path)
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			return nil, err
		}
		reader = strings.NewReader(string(data))
	} else {
		f, err := os.Open(path)
		if err != nil {
			return nil, err
		}
		defer f.Close()
		data, err := io.ReadAll(f)
		if err != nil {
			return nil, err
		}
		reader = strings.NewReader(string(data))
	}

	img, _, err := image.Decode(reader)
	return img, err
}

// Lanczos kernel function  
func lanczosKernel(x float64) float64 {
	const a = 3.0
	if x == 0 {
		return 1.0
	}
	if math.Abs(x) >= a {
		return 0.0
	}
	pix := math.Pi * x
	return (math.Sin(pix) / pix) * (math.Sin(pix/a) / (pix / a))
}

func clampFloat(v float64) float64 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return v
}

func clampUint8(v float64) uint8 {
	return uint8(clampFloat(v) + 0.5)
}

// getNRGBA extracts NRGBA color from image
func getNRGBA(img image.Image, x, y int) color.NRGBA {
	bounds := img.Bounds()
	if x < bounds.Min.X {
		x = bounds.Min.X
	} else if x >= bounds.Max.X {
		x = bounds.Max.X - 1
	}
	if y < bounds.Min.Y {
		y = bounds.Min.Y
	} else if y >= bounds.Max.Y {
		y = bounds.Max.Y - 1
	}
	return toNRGBA(img.At(x, y))
}

func toNRGBA(c color.Color) color.NRGBA {
	r, g, b, a := c.RGBA()
	if a == 0 {
		return color.NRGBA{0, 0, 0, 0}
	}
	return color.NRGBA{
		R: uint8(r * 0xFFFF / a >> 8),
		G: uint8(g * 0xFFFF / a >> 8),
		B: uint8(b * 0xFFFF / a >> 8),
		A: uint8(a >> 8),
	}
}

// resizeImage resizes an image using Lanczos resampling (matches imaging package behavior)
func resizeImage(img image.Image, width, height int) *image.NRGBA {
	srcBounds := img.Bounds()
	srcW := srcBounds.Max.X - srcBounds.Min.X
	srcH := srcBounds.Max.Y - srcBounds.Min.Y

	if srcW == 0 || srcH == 0 {
		return image.NewNRGBA(image.Rect(0, 0, width, height))
	}

	dst := image.NewNRGBA(image.Rect(0, 0, width, height))

	const a = 3.0

	scaleX := float64(srcW) / float64(width)
	scaleY := float64(srcH) / float64(height)

	for dstY := 0; dstY < height; dstY++ {
		srcYf := (float64(dstY)+0.5)*scaleY - 0.5

		for dstX := 0; dstX < width; dstX++ {
			srcXf := (float64(dstX)+0.5)*scaleX - 0.5

			var rSum, gSum, bSum, aSum, wSum float64

			minSY := int(math.Floor(srcYf - a*scaleY + 1))
			maxSY := int(math.Ceil(srcYf + a*scaleY - 1))
			minSX := int(math.Floor(srcXf - a*scaleX + 1))
			maxSX := int(math.Ceil(srcXf + a*scaleX - 1))

			for sy := minSY; sy <= maxSY; sy++ {
				wy := lanczosKernel((srcYf - float64(sy)) / scaleY)
				if wy == 0 {
					continue
				}
				for sx := minSX; sx <= maxSX; sx++ {
					wx := lanczosKernel((srcXf - float64(sx)) / scaleX)
					if wx == 0 {
						continue
					}
					w := wx * wy
					px := getNRGBA(img, sx+srcBounds.Min.X, sy+srcBounds.Min.Y)
					fA := float64(px.A) / 255.0
					rSum += float64(px.R) * fA * w
					gSum += float64(px.G) * fA * w
					bSum += float64(px.B) * fA * w
					aSum += fA * w
					wSum += w
				}
			}

			if wSum != 0 {
				alF := aSum / wSum * 255.0
				al := clampUint8(alF)
				var r, g, b uint8
				if aSum > 0 {
					r = clampUint8(rSum / (aSum / 255.0))
					g = clampUint8(gSum / (aSum / 255.0))
					b = clampUint8(bSum / (aSum / 255.0))
				}
				dst.SetNRGBA(dstX, dstY, color.NRGBA{r, g, b, al})
			}
		}
	}
	return dst
}

// fillImage fills exact dimensions by resize+crop
func fillImage(img image.Image, width, height int) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Max.X - srcBounds.Min.X
	srcH := srcBounds.Max.Y - srcBounds.Min.Y

	scaleX := float64(width) / float64(srcW)
	scaleY := float64(height) / float64(srcH)
	scale := math.Max(scaleX, scaleY)

	newW := int(math.Round(float64(srcW) * scale))
	newH := int(math.Round(float64(srcH) * scale))

	resized := resizeImage(img, newW, newH)

	offsetX := (newW - width) / 2
	offsetY := (newH - height) / 2

	dst := image.NewNRGBA(image.Rect(0, 0, width, height))
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			dst.SetNRGBA(x, y, resized.NRGBAAt(x+offsetX, y+offsetY))
		}
	}
	return dst
}

// fitImage fits within dimensions maintaining aspect ratio
func fitImage(img image.Image, width, height int) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Max.X - srcBounds.Min.X
	srcH := srcBounds.Max.Y - srcBounds.Min.Y

	scaleX := float64(width) / float64(srcW)
	scaleY := float64(height) / float64(srcH)
	scale := math.Min(scaleX, scaleY)

	newW := int(math.Round(float64(srcW) * scale))
	newH := int(math.Round(float64(srcH) * scale))

	return resizeImage(img, newW, newH)
}

// applyMatte blends pixel with matte color
func applyMatte(c color.NRGBA, matte color.RGBA) color.RGBA {
	alpha := float64(c.A) / 255.0
	r := uint8(math.Round(float64(c.R)*alpha + float64(matte.R)*(1.0-alpha)))
	g := uint8(math.Round(float64(c.G)*alpha + float64(matte.G)*(1.0-alpha)))
	b := uint8(math.Round(float64(c.B)*alpha + float64(matte.B)*(1.0-alpha)))
	return color.RGBA{r, g, b, 255}
}

// brightness computes max(R, G, B)
func brightness(c color.RGBA) uint8 {
	m := c.R
	if c.G > m {
		m = c.G
	}
	if c.B > m {
		m = c.B
	}
	return m
}

func getDitherBlockChar(b uint8) rune {
	switch {
	case b >= 205:
		return '█'
	case b >= 153:
		return '▓'
	case b >= 101:
		return '▒'
	case b >= 49:
		return '░'
	default:
		return ' '
	}
}

func getDitherAsciiChar(b uint8) rune {
	switch {
	case b >= 231:
		return '#'
	case b >= 208:
		return '&'
	case b >= 185:
		return '$'
	case b >= 162:
		return 'X'
	case b >= 139:
		return 'x'
	case b >= 116:
		return '='
	case b >= 93:
		return '+'
	case b >= 70:
		return ';'
	case b >= 47:
		return ':'
	case b >= 24:
		return '.'
	default:
		return ' '
	}
}

func init() {
	// Register BMP format
	image.RegisterFormat("bmp", "BM", decodeBMP, decodeBMPConfig)
}

// Minimal BMP decoder
func decodeBMPConfig(r io.Reader) (image.Config, error) {
	img, err := decodeBMP(r)
	if err != nil {
		return image.Config{}, err
	}
	b := img.Bounds()
	return image.Config{
		ColorModel: color.RGBAModel,
		Width:      b.Max.X,
		Height:     b.Max.Y,
	}, nil
}

func decodeBMP(r io.Reader) (image.Image, error) {
	// Read BMP header
	var signature [2]byte
	if _, err := io.ReadFull(r, signature[:]); err != nil {
		return nil, err
	}
	if signature[0] != 'B' || signature[1] != 'M' {
		return nil, fmt.Errorf("not a BMP file")
	}

	var fileSize uint32
	if err := binary.Read(r, binary.LittleEndian, &fileSize); err != nil {
		return nil, err
	}

	var reserved uint32
	if err := binary.Read(r, binary.LittleEndian, &reserved); err != nil {
		return nil, err
	}

	var dataOffset uint32
	if err := binary.Read(r, binary.LittleEndian, &dataOffset); err != nil {
		return nil, err
	}

	// DIB header size
	var headerSize uint32
	if err := binary.Read(r, binary.LittleEndian, &headerSize); err != nil {
		return nil, err
	}

	var width, height int32
	if err := binary.Read(r, binary.LittleEndian, &width); err != nil {
		return nil, err
	}
	if err := binary.Read(r, binary.LittleEndian, &height); err != nil {
		return nil, err
	}

	var planes, bitsPerPixel uint16
	binary.Read(r, binary.LittleEndian, &planes)
	binary.Read(r, binary.LittleEndian, &bitsPerPixel)

	var compression uint32
	binary.Read(r, binary.LittleEndian, &compression)

	// Skip rest of header
	remaining := int(headerSize) - 20 + 4 // 20 = already read (4+4+4+2+2+4)... let me recalc
	// headerSize itself is 4 bytes (already read)
	// Then we read: width(4)+height(4)+planes(2)+bitsPerPixel(2)+compression(4) = 16 more bytes
	// Total read after headerSize: 16 bytes
	// Need to skip: headerSize - 4 - 16 bytes more? Actually headerSize includes itself in BITMAPINFOHEADER
	// Actually headerSize does NOT include the 4 bytes of headerSize itself... let me be careful.
	// BITMAPINFOHEADER is 40 bytes total, starting with headerSize(4).
	// We've read: headerSize(4) + width(4) + height(4) + planes(2) + bitsPerPixel(2) + compression(4) = 20 bytes
	// Need to skip: 40 - 20 = 20 more bytes of the DIB header
	remaining = int(headerSize) - 16 // headerSize includes itself? Actually no, headerSize IS the first 4 bytes
	// The total DIB header size is headerSize (not including the headerSize field itself in some formats)
	// For BITMAPINFOHEADER: headerSize = 40, total = 40 bytes starting from headerSize field
	// We read headerSize(4) + width(4) + height(4) + planes(2) + bpp(2) + compression(4) = 20 bytes
	// Still need to read: 40 - 20 = 20 more bytes
	remaining = int(headerSize) - 16
	skipBuf := make([]byte, remaining)
	io.ReadFull(r, skipBuf)
	_ = planes
	_ = compression
	_ = reserved

	flipVertically := height > 0
	if height < 0 {
		height = -height
	}

	img := image.NewRGBA(image.Rect(0, 0, int(width), int(height)))

	bytesPerPixel := int(bitsPerPixel) / 8
	rowSize := ((int(width)*int(bitsPerPixel) + 31) / 32) * 4

	row := make([]byte, rowSize)
	for y := 0; y < int(height); y++ {
		io.ReadFull(r, row)
		dstY := y
		if flipVertically {
			dstY = int(height) - 1 - y
		}
		for x := 0; x < int(width); x++ {
			offset := x * bytesPerPixel
			var rv, gv, bv, av uint8
			switch bitsPerPixel {
			case 24:
				bv = row[offset]
				gv = row[offset+1]
				rv = row[offset+2]
				av = 255
			case 32:
				bv = row[offset]
				gv = row[offset+1]
				rv = row[offset+2]
				av = row[offset+3]
			default:
				rv, gv, bv, av = 0, 0, 0, 255
			}
			img.SetRGBA(x, dstY, color.RGBA{rv, gv, bv, av})
		}
	}
	return img, nil
}

func main() {
	flag.IntVar(&flagDither, "d", 0, "dithering mode")
	flag.BoolVar(&flagGo, "go", false, "output Go code")
	flag.StringVar(&flagMatte, "m", "000000", "matte color")
	flag.BoolVar(&flagNoBg, "nobg", false, "disable background color")
	flag.IntVar(&flagScale, "s", 0, "scale method")
	flag.IntVar(&flagRows, "tr", 0, "terminal rows")
	flag.IntVar(&flagCols, "tc", 0, "terminal columns")
	flag.BoolVar(&flagVersion, "version", false, "show version")
	flag.BoolVar(&flagCredits, "credits", false, "show credits")

	var flagHelp bool
	flag.BoolVar(&flagHelp, "help", false, "show help")

	flag.Usage = usage
	flag.Parse()

	if flagHelp {
		usage()
		return
	}

	if flagVersion {
		fmt.Println(appVersion)
		return
	}

	if flagCredits {
		credits()
		return
	}

	if flag.NArg() < 1 {
		usage()
		return
	}

	imagePath := flag.Arg(0)

	matteColor, err := parseHexColor(flagMatte)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error parsing matte color: %v\n", err)
		os.Exit(1)
	}

	img, err := loadImage(imagePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error loading image: %v\n", err)
		os.Exit(1)
	}

	// Get terminal size
	termCols, termRows := getTerminalSize()
	if flagCols >= 2 {
		termCols = flagCols
	}
	if flagRows >= 2 {
		termRows = flagRows
	}

	// Scale image
	var scaledImg image.Image
	if flagDither == 0 {
		targetH := termRows * 2
		targetW := termCols
		switch flagScale {
		case 1:
			scaledImg = fillImage(img, targetW, targetH)
		case 2:
			scaledImg = fitImage(img, targetW, targetH)
		default:
			scaledImg = resizeImage(img, targetW, targetH)
		}
	} else {
		targetH := termRows
		targetW := termCols
		switch flagScale {
		case 1:
			scaledImg = fillImage(img, targetW, targetH)
		case 2:
			scaledImg = fitImage(img, targetW, targetH)
		default:
			scaledImg = resizeImage(img, targetW, targetH)
		}
	}

	bounds := scaledImg.Bounds()
	imgW := bounds.Max.X - bounds.Min.X
	imgH := bounds.Max.Y - bounds.Min.Y

	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	if flagDither == 0 {
		for y := 0; y < imgH-1; y += 2 {
			if flagGo {
				fmt.Fprintf(writer, "fmt.Print(\"")
			}
			for x := 0; x < imgW; x++ {
				topC := scaledImg.At(x+bounds.Min.X, y+bounds.Min.Y)
				botC := scaledImg.At(x+bounds.Min.X, y+1+bounds.Min.Y)

				top := applyMatte(toNRGBA(topC), matteColor)
				bot := applyMatte(toNRGBA(botC), matteColor)

				if flagGo {
					fmt.Fprintf(writer, "\\033[48;2;%d;%d;%dm\\033[38;2;%d;%d;%dm▄",
						top.R, top.G, top.B, bot.R, bot.G, bot.B)
				} else {
					fmt.Fprintf(writer, "\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm▄",
						top.R, top.G, top.B, bot.R, bot.G, bot.B)
				}
			}
			if flagGo {
				fmt.Fprintf(writer, "\\033[0m\\n\")\n")
			} else {
				fmt.Fprintf(writer, "\x1b[0m\n")
			}
		}
	} else {
		for y := 0; y < imgH; y++ {
			if flagGo {
				fmt.Fprintf(writer, "fmt.Print(\"")
			}
			for x := 0; x < imgW; x++ {
				c := scaledImg.At(x+bounds.Min.X, y+bounds.Min.Y)
				col := applyMatte(toNRGBA(c), matteColor)
				br := brightness(col)

				var ch rune
				if flagDither == 1 {
					ch = getDitherBlockChar(br)
				} else {
					ch = getDitherAsciiChar(br)
				}

				if flagNoBg {
					if flagGo {
						fmt.Fprintf(writer, "\\033[38;2;%d;%d;%dm%c",
							col.R, col.G, col.B, ch)
					} else {
						fmt.Fprintf(writer, "\x1b[38;2;%d;%d;%dm%c",
							col.R, col.G, col.B, ch)
					}
				} else {
					if flagGo {
						fmt.Fprintf(writer, "\\033[48;2;%d;%d;%dm\\033[38;2;%d;%d;%dm%c",
							matteColor.R, matteColor.G, matteColor.B,
							col.R, col.G, col.B, ch)
					} else {
						fmt.Fprintf(writer, "\x1b[48;2;%d;%d;%dm\x1b[38;2;%d;%d;%dm%c",
							matteColor.R, matteColor.G, matteColor.B,
							col.R, col.G, col.B, ch)
					}
				}
			}
			if flagGo {
				fmt.Fprintf(writer, "\\033[0m\\n\")\n")
			} else {
				fmt.Fprintf(writer, "\x1b[0m\n")
			}
		}
	}
}

