package main

import (
	"image"
	"image/color"
	"math"
)

// Lanczos3 kernel
func lanczos3(x float64) float64 {
	const a = 3.0
	if x == 0 {
		return 1.0
	}
	if math.Abs(x) >= a {
		return 0.0
	}
	pix := math.Pi * x
	return (math.Sin(pix) / pix) * (math.Sin(pix/a) / (pix / a))
}

// resizeHorizontal resizes image horizontally using Lanczos3
func resizeHorizontal(src *image.NRGBA, dstWidth int) *image.NRGBA {
	srcBounds := src.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()

	if srcW == dstWidth {
		return src
	}

	scale := float64(dstWidth) / float64(srcW)
	// For downsampling, step > 1; for upsampling, step = 1
	step := 1.0
	if scale < 1.0 {
		step = 1.0 / scale
	}
	support := 3.0 * step // kernel support radius in source space

	dst := image.NewNRGBA(image.Rect(0, 0, dstWidth, srcH))

	for dstX := 0; dstX < dstWidth; dstX++ {
		// Source position (center of the dst pixel mapped to src space)
		srcXf := (float64(dstX)+0.5)/scale - 0.5

		minSX := int(math.Floor(srcXf - support + 0.5))
		maxSX := int(math.Ceil(srcXf + support - 0.5))

		// Compute weights
		weights := make([]float64, maxSX-minSX+1)
		var wSum float64
		for i, sx := range irange(minSX, maxSX) {
			w := lanczos3((srcXf - float64(sx)) / step)
			weights[i] = w
			wSum += w
		}

		for dstY := 0; dstY < srcH; dstY++ {
			var rSum, gSum, bSum, aSum float64
			for i, sx := range irange(minSX, maxSX) {
				cx := sx
				if cx < srcBounds.Min.X {
					cx = srcBounds.Min.X
				} else if cx >= srcBounds.Max.X {
					cx = srcBounds.Max.X - 1
				}
				w := weights[i]
				if wSum != 0 {
					w /= wSum
				}
				px := src.NRGBAAt(cx, dstY+srcBounds.Min.Y)
				fA := float64(px.A)
				rSum += float64(px.R) * fA * w
				gSum += float64(px.G) * fA * w
				bSum += float64(px.B) * fA * w
				aSum += fA * w
			}
			var r, g, b, al uint8
			if aSum > 0 {
				al = clampU8(aSum)
				r = clampU8(rSum / aSum * 255.0)
				g = clampU8(gSum / aSum * 255.0)
				b = clampU8(bSum / aSum * 255.0)
			} else {
				al = clampU8(aSum)
			}
			dst.SetNRGBA(dstX, dstY, color.NRGBA{r, g, b, al})
		}
	}
	return dst
}

// resizeVertical resizes image vertically using Lanczos3
func resizeVertical(src *image.NRGBA, dstHeight int) *image.NRGBA {
	srcBounds := src.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()

	if srcH == dstHeight {
		return src
	}

	scale := float64(dstHeight) / float64(srcH)
	step := 1.0
	if scale < 1.0 {
		step = 1.0 / scale
	}
	support := 3.0 * step

	dst := image.NewNRGBA(image.Rect(0, 0, srcW, dstHeight))

	for dstY := 0; dstY < dstHeight; dstY++ {
		srcYf := (float64(dstY)+0.5)/scale - 0.5

		minSY := int(math.Floor(srcYf - support + 0.5))
		maxSY := int(math.Ceil(srcYf + support - 0.5))

		weights := make([]float64, maxSY-minSY+1)
		var wSum float64
		for i, sy := range irange(minSY, maxSY) {
			w := lanczos3((srcYf - float64(sy)) / step)
			weights[i] = w
			wSum += w
		}

		for dstX := 0; dstX < srcW; dstX++ {
			var rSum, gSum, bSum, aSum float64
			for i, sy := range irange(minSY, maxSY) {
				cy := sy
				if cy < srcBounds.Min.Y {
					cy = srcBounds.Min.Y
				} else if cy >= srcBounds.Max.Y {
