const (
	lanczos3Support = 3.0
)

// lanczos3Kernel computes the Lanczos3 kernel value
func lanczos3Kernel(x float64) float64 {
	x = math.Abs(x)
	if x >= lanczos3Support {
		return 0
	}
	if x == 0 {
		return 1
	}
	xPi := x * math.Pi
	return math.Sin(xPi) / xPi * math.Sin(xPi/lanczos3Support) / (xPi / lanczos3Support)
