func makeHorizontalFilter(srcW, dstW int) horizontalFilter {
	srcStep := float64(srcW) / float64(dstW)
	var filterRadius, normFactor float64
	if srcStep > 1.0 {
		// Downsampling
		filterRadius = lanczos3Support * srcStep
		normFactor = 1.0 / srcStep
	} else {
		// Upsampling
		filterRadius = lanczos3Support
		normFactor = 1.0
	}

	hf := horizontalFilter{
		weights: make([][]float64, dstW),
		offsets: make([]int, dstW),
	}

	for dstX := 0; dstX < dstW; dstX++ {
