		start := int(math.Floor(srcXf - filterRadius + 0.5))
		stop := int(math.Ceil(srcXf + filterRadius - 0.5))
		if start < 0 {
			start = 0
		}
		if stop >= srcW {
			stop = srcW - 1
		}

		count := stop - start + 1
		weights := make([]float64, count)
		var wSum float64
		for i := 0; i < count; i++ {
			sx := start + i
			w := lanczos3Kernel((srcXf - float64(sx)) * normFactor)
			weights[i] = w
			wSum += w
		}
		if wSum != 0 {
			for i := range weights {
				weights[i] /= wSum
			}
		}

		hf.weights[dstX] = weights
		hf.offsets[dstX] = start
	}
	return hf
}

