	weights [][]float64
	offsets []int
}

func makeVerticalFilter(srcH, dstH int) verticalFilter {
	srcStep := float64(srcH) / float64(dstH)
	var filterRadius, normFactor float64
	if srcStep > 1.0 {
		filterRadius = lanczos3Support * srcStep
		normFactor = 1.0 / srcStep
	} else {
