package main

import (
	"image"
	"image/color"
	"math"
)

const (
	lanczos3Support = 3.0
)

func lanczos3At(x float64) float64 {
	x = math.Abs(x)
	if x >= lanczos3Support {
		return 0
	}
	if x == 0 {
		return 1
	}
	xPi := x * math.Pi
	return math.Sin(xPi) / xPi * math.Sin(xPi/lanczos3Support) / (xPi / lanczos3Support)
}

type filterWeights struct {
	weights [][]float64
	offsets []int
}

func makeFilterWeights(srcSize, dstSize int) filterWeights {
	srcStep := float64(srcSize) / float64(dstSize)
	var filterRadius, normFactor float64
	if srcStep > 1.0 {
		filterRadius = lanczos3Support * srcStep
		normFactor = 1.0 / srcStep
	} else {
		filterRadius = lanczos3Support
		normFactor = 1.0
	}

	fw := filterWeights{
		weights: make([][]float64, dstSize),
		offsets: make([]int, dstSize),
	}

	for dstPos := 0; dstPos < dstSize; dstPos++ {
		srcPosf := (float64(dstPos)+0.5)*srcStep - 0.5

		start := int(math.Floor(srcPosf - filterRadius + 0.5))
		stop := int(math.Ceil(srcPosf + filterRadius - 0.5))
		if start < 0 {
			start = 0
		}
		if stop >= srcSize {
			stop = srcSize - 1
		}

		count := stop - start + 1
		weights := make([]float64, count)
		var wSum float64
		for i := 0; i < count; i++ {
			w := lanczos3At((srcPosf - float64(start+i)) * normFactor)
			weights[i] = w
			wSum += w
		}
		if wSum != 0 {
			for i := range weights {
				weights[i] /= wSum
			}
		}

		fw.weights[dstPos] = weights
		fw.offsets[dstPos] = start
	}
	return fw
}

// Float pixel for intermediate storage (no quantization)
type floatPixel struct {
	r, g, b, a float64
}

func clampU8(v float64) uint8 {
	if v <= 0 {
		return 0
	}
	if v >= 255 {
		return 255
	}
	return uint8(v + 0.5)
}

func toNRGBAImg(img image.Image) *image.NRGBA {
	bounds := img.Bounds()
	dst := image.NewNRGBA(image.Rect(0, 0, bounds.Dx(), bounds.Dy()))
	for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
		for x := bounds.Min.X; x < bounds.Max.X; x++ {
			dst.SetNRGBA(x-bounds.Min.X, y-bounds.Min.Y, toNRGBA(img.At(x, y)))
		}
	}
	return dst
}

// resizeImageLanczos resizes using two-pass Lanczos with float64 intermediate
func resizeImageLanczos(img image.Image, width, height int) *image.NRGBA {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()

	if srcW == 0 || srcH == 0 {
		return image.NewNRGBA(image.Rect(0, 0, width, height))
	}

	src := toNRGBAImg(img)

	// Pass 1: horizontal resize (srcW -> width), result is float64
	hfw := makeFilterWeights(srcW, width)

	// Intermediate: width x srcH, as float64
	intermediate := make([]floatPixel, width*srcH)
	for dstX := 0; dstX < width; dstX++ {
		weights := hfw.weights[dstX]
		offset := hfw.offsets[dstX]

		for y := 0; y < srcH; y++ {
			var rSum, gSum, bSum, aSum float64
			for i, w := range weights {
				sx := offset + i
				px := src.NRGBAAt(sx, y)
				fA := float64(px.A) / 255.0
				rSum += float64(px.R) * fA * w
				gSum += float64(px.G) * fA * w
				bSum += float64(px.B) * fA * w
				aSum += fA * w
			}
			intermediate[y*width+dstX] = floatPixel{rSum, gSum, bSum, aSum}
		}
	}

	// Pass 2: vertical resize (srcH -> height) using float64 intermediate
	vfw := makeFilterWeights(srcH, height)

	dst := image.NewNRGBA(image.Rect(0, 0, width, height))
	for dstY := 0; dstY < height; dstY++ {
		weights := vfw.weights[dstY]
		offset := vfw.offsets[dstY]

		for x := 0; x < width; x++ {
			var rSum, gSum, bSum, aSum float64
			for i, w := range weights {
				sy := offset + i
				fp := intermediate[sy*width+x]
				rSum += fp.r * w
				gSum += fp.g * w
				bSum += fp.b * w
				aSum += fp.a * w
			}
			var r, g, b, al uint8
			if aSum > 0 {
				al = clampU8(aSum * 255.0)
				r = clampU8(rSum / aSum)
				g = clampU8(gSum / aSum)
				b = clampU8(bSum / aSum)
			} else {
				al = clampU8(aSum * 255.0)
			}
			dst.SetNRGBA(x, dstY, color.NRGBA{r, g, b, al})
		}
	}
	return dst
}

func fillImageLanczos(img image.Image, width, height int) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()

	scaleX := float64(width) / float64(srcW)
	scaleY := float64(height) / float64(srcH)
	scale := math.Max(scaleX, scaleY)

	newW := int(math.Round(float64(srcW) * scale))
	newH := int(math.Round(float64(srcH) * scale))

	resized := resizeImageLanczos(img, newW, newH)

	offsetX := (newW - width) / 2
	offsetY := (newH - height) / 2

	dst := image.NewNRGBA(image.Rect(0, 0, width, height))
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			cx := x + offsetX
			cy := y + offsetY
			if cx < 0 {
				cx = 0
			}
			if cx >= newW {
				cx = newW - 1
			}
			if cy < 0 {
				cy = 0
			}
			if cy >= newH {
				cy = newH - 1
			}
			dst.SetNRGBA(x, y, resized.NRGBAAt(cx, cy))
		}
	}
	return dst
}

func fitImageLanczos(img image.Image, width, height int) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()

	scaleX := float64(width) / float64(srcW)
	scaleY := float64(height) / float64(srcH)
	scale := math.Min(scaleX, scaleY)

	newW := int(math.Round(float64(srcW) * scale))
	newH := int(math.Round(float64(srcH) * scale))

	return resizeImageLanczos(img, newW, newH)
}
