			for i, wi := range w {
				px := src.NRGBAAt(off+i, y)
				fA := float64(px.A) / 255.0
				rSum += float64(px.R) * fA * wi
				gSum += float64(px.G) * fA * wi
				bSum += float64(px.B) * fA * wi
				aSum += fA * wi
			}
			var r, g, b, al uint8
			if aSum > 0 {
				al = clampU8(aSum * 255.0)
				r = clampU8(rSum / aSum)
				g = clampU8(gSum / aSum)
				b = clampU8(bSum / aSum)
			} else {
				al = clampU8(aSum * 255.0)
			}
			dst.SetNRGBA(dstX, y, color.NRGBA{r, g, b, al})
		}
	}
	return dst
}

func resizeVert(src *image.NRGBA, dstHeight int) *image.NRGBA {
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	if srcH == dstHeight {
		return src
	}
	weights, offsets := makeFilterWeights(srcH, dstHeight)
	dst := image.NewNRGBA(image.Rect(0, 0, srcW, dstHeight))
	for dstY := 0; dstY < dstHeight; dstY++ {
		w := weights[dstY]
		off := offsets[dstY]
		for x := 0; x < srcW; x++ {
			var rSum, gSum, bSum, aSum float64
			for i, wi := range w {
				px := src.NRGBAAt(x, off+i)
				fA := float64(px.A) / 255.0
				rSum += float64(px.R) * fA * wi
				gSum += float64(px.G) * fA * wi
				bSum += float64(px.B) * fA * wi
				aSum += fA * wi
			}
			var r, g, b, al uint8
			if aSum > 0 {
				al = clampU8(aSum * 255.0)
				r = clampU8(rSum / aSum)
				g = clampU8(gSum / aSum)
				b = clampU8(bSum / aSum)
			} else {
				al = clampU8(aSum * 255.0)
			}
			dst.SetNRGBA(x, dstY, color.NRGBA{r, g, b, al})
		}
	}
	return dst
}

func resizeImageLanczos(img image.Image, width, height int) *image.NRGBA {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()

	if srcW == 0 || srcH == 0 {
		return image.NewNRGBA(image.Rect(0, 0, width, height))
	}

	src := toNRGBAImg(img)
	// Horizontal first, then vertical
	intermediate := resizeHoriz(src, width)
	result := resizeVert(intermediate, height)
	return result
}

func fillImageLanczos(img image.Image, width, height int) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()

	scaleX := float64(width) / float64(srcW)
	scaleY := float64(height) / float64(srcH)
	scale := math.Max(scaleX, scaleY)

	newW := int(math.Round(float64(srcW) * scale))
	newH := int(math.Round(float64(srcH) * scale))

	resized := resizeImageLanczos(img, newW, newH)

	offsetX := (newW - width) / 2
	offsetY := (newH - height) / 2

	dst := image.NewNRGBA(image.Rect(0, 0, width, height))
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			cx := x + offsetX
			cy := y + offsetY
			if cx < 0 {
				cx = 0
			}
			if cx >= newW {
				cx = newW - 1
			}
			if cy < 0 {
				cy = 0
			}
			if cy >= newH {
				cy = newH - 1
			}
			dst.SetNRGBA(x, y, resized.NRGBAAt(cx, cy))
		}
	}
	return dst
}

func fitImageLanczos(img image.Image, width, height int) image.Image {
	srcBounds := img.Bounds()
	srcW := srcBounds.Dx()
	srcH := srcBounds.Dy()

	scaleX := float64(width) / float64(srcW)
	scaleY := float64(height) / float64(srcH)
	scale := math.Min(scaleX, scaleY)

	newW := int(math.Round(float64(srcW) * scale))
	newH := int(math.Round(float64(srcH) * scale))

	return resizeImageLanczos(img, newW, newH)
}
