package main

import (
    "fmt"
    "syscall"
    "unsafe"
    "os"
)

type winsize struct {
    Row    uint16
    Col    uint16
    Xpixel uint16
    Ypixel uint16
}

func tryTerminalSize(fd int) (int, int, bool) {
    ws := &winsize{}
    ret, _, _ := syscall.Syscall(syscall.SYS_IOCTL,
        uintptr(fd),
        uintptr(syscall.TIOCGWINSZ),
        uintptr(unsafe.Pointer(ws)))
    if int(ret) != -1 && ws.Col > 0 && ws.Row > 0 {
        return int(ws.Col), int(ws.Row), true
    }
    return 0, 0, false
}

func main() {
    // Try /dev/tty
    tty, err := os.Open("/dev/tty")
    if err == nil {
        defer tty.Close()
        w, h, ok := tryTerminalSize(int(tty.Fd()))
        if ok {
            fmt.Printf("/dev/tty: %dx%d\n", w, h)
        } else {
            fmt.Println("/dev/tty: failed")
        }
    } else {
        fmt.Printf("Can't open /dev/tty: %v\n", err)
    }

    // Try standard fds
    for i := 0; i < 3; i++ {
        w, h, ok := tryTerminalSize(i)
        if ok {
            fmt.Printf("fd=%d: %dx%d\n", i, w, h)
        }
    }
}
